package com.autoops.ai.controller;import com.autoops.ai.provider.AIProvider;import com.autoops.ai.service.AIService;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/ai")public class AIController{private final AIService service;public AIController(AIService s){service=s;}public record ChatRequest(String message){}@PostMapping("/chat")public AIProvider.AIResponse chat(@RequestBody ChatRequest r){return service.chat(r.message());}}
